static bool parse_heap_entries(zcbor_state_t *state, void *user_data)
{
	struct memory_pools_info_t *receive_data = (struct memory_pools_info_t *)user_data;
	bool ok;
	uint8_t temp_heap_idx = 0; // Temporary index for populating receive_data->heaps

	receive_data->current_heap_count = 0;
	receive_data->found_common_malloc = false;
	receive_data->found_kernel_malloc = false;
	receive_data->common_malloc_idx = 255;
	receive_data->kernel_malloc_idx = 255;

	if (!zcbor_map_start_decode(state)) {
		return false;
	}

	while (!zcbor_map_at_end(state)) { // Changed from zcbor_array_at_end
		size_t decoded = 0;
		struct zcbor_string block_name;
		struct heap_info_t *heap_data;

		zassert_not_equal(receive_data->current_heap_count, TEST_MAX_HEAPS,
				  "More heaps than were expected");

		ok = zcbor_tstr_decode(state, &block_name);
		zassert_true(ok, "Expected to get name of memory block");

		// Determine which heap this is and assign to the correct index in receive_data->heaps
		if (block_name.len == strlen("malloc") &&
		    memcmp(block_name.value, "malloc", block_name.len) == 0) {
			zassert_false(receive_data->found_common_malloc, "Duplicate malloc heap entry");
			receive_data->found_common_malloc = true;
			receive_data->common_malloc_idx = temp_heap_idx;
			heap_data = &receive_data->heaps[temp_heap_idx];
		} else if (block_name.len == strlen("k_heap") &&
			   memcmp(block_name.value, "k_heap", block_name.len) == 0) {
			zassert_false(receive_data->found_kernel_malloc, "Duplicate k_heap entry");
			receive_data->found_kernel_malloc = true;
			receive_data->kernel_malloc_idx = temp_heap_idx;
			heap_data = &receive_data->heaps[temp_heap_idx];
		} else {
			zassert_true(false, "Unknown heap name received: %.*s", block_name.len, block_name.value);
			return false;
		}

		struct zcbor_map_decode_key_val output_decode[] = {
			ZCBOR_MAP_DECODE_KEY_DECODER("blksiz", zcbor_uint32_decode,
						     &heap_data->block_size),
			ZCBOR_MAP_DECODE_KEY_DECODER("nblks", zcbor_uint32_decode,
						     &heap_data->total_blocks),
			ZCBOR_MAP_DECODE_KEY_DECODER("nfree", zcbor_uint32_decode,
						     &heap_data->free_blocks),
			ZCBOR_MAP_DECODE_KEY_DECODER("min", zcbor_uint32_decode,
						     &heap_data->minimum_blocks),
		};

		ok = zcbor_map_decode_bulk(state, output_decode, ARRAY_SIZE(output_decode),
					   &decoded) == 0;
		zassert_true(ok, "Expected decode to be successful");

#ifdef CONFIG_MCUMGR_GRP_OS_MPSTAT_ONLY_SUPPORTED_STATS
		zassert_true((decoded == 3),
			     "Expected to receive 3 decoded zcbor elements");
		zassert_false(zcbor_map_decode_bulk_key_found(output_decode,
							     ARRAY_SIZE(output_decode), "blksiz"),
			     "Did not expect to find blksize value");
#else
		zassert_true((decoded == 4),
			     "Expected to receive 4 decoded zcbor elements");
		zassert_equal(heap_data->block_size, 1,
			      "Expected memory block size to match expected value");
#endif

		zassert_true(zcbor_map_decode_bulk_key_found(output_decode,
							     ARRAY_SIZE(output_decode), "nblks"),
			     "Expected to find nblks value");
		zassert_true(zcbor_map_decode_bulk_key_found(output_decode,
							     ARRAY_SIZE(output_decode), "nfree"),
			     "Expected to find nfree value");
		zassert_true(zcbor_map_decode_bulk_key_found(output_decode,
							     ARRAY_SIZE(output_decode), "min"),
			     "Expected to find min value");

		++receive_data->current_heap_count;
		++temp_heap_idx;
	}

	(void)zcbor_map_end_decode(state);

	zassert_equal(receive_data->current_heap_count, TEST_MAX_HEAPS, "Less heaps than were expected");
	zassert_true(receive_data->found_common_malloc, "Common malloc heap not found");
	zassert_true(receive_data->found_kernel_malloc, "Kernel malloc heap not found");

	return true;
}

